ic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.",},__ru={"Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.",},},parentQuest=0,preQuestSingle={4734,},questFlags=64,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{10267,},},zoneOrSort=1583,},[4742]={finishedBy={{10299,},},name={__en="Seal of Ascension",__ru="Печать Вознесения",},nextQuestInChain=4743,objectives={[3]={{12336,[3]=0,},{12335,[3]=0,},{12337,[3]=0,},{12219,[3]=0,},},},objectivesText={__en={"Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.","","The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe.",},__ru={"Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.","","Камни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{10299,},},zoneOrSort=1583,},[4743]={finishedBy={{10299,},},name={__en="Seal of Ascension",__ru="Печать Вознесения",},nextQuestInChain=0,objectives={[3]={{12324,[3]=0,},},},objectivesText={__en={"Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.","","It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!",},__ru={"Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.","","Как только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати Вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку.",},},parentQuest=0,preQuestSingle={4742,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{10299,},},zoneOrSort=1583,},[4764]={finishedBy={{9565,},},name={__en="Doomrigger's Clasp",__ru="Пряжка Роковой оснастки",},nextQuestInChain=4765,objectives={[3]={{12352,[3]=0,},},},objectivesText={__en={"Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.",},__ru={"Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи.",},},parentQuest=0,questFlags=72,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=4294967373,specialFlags=0,startedBy={{9565,},},zoneOrSort=1583,},[4765]={finishedBy={{2285,},},name={__en="Delivery to Ridgewell",__ru="Доставить Риджвеллу",},nextQuestInChain=0,objectives={},objectivesText={__en={"Bring Ridgewell's Crate to Remington Ridgewell in Stormwind.",},__ru={"Отнесите ящик Риджвелла Ремингтону Риджвеллу в Штормград.",},},parentQuest=0,preQuestSingle={4764,},questFlags=64,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=4294967373,specialFlags=0,startedBy={{9565,},},zoneOrSort=1583,},[4766]={finishedBy={{9565,},},name={__en="Mayara Brightwing",__ru="Майра Светлое Крыло",},nextQuestInChain=4764,objectives={},objectivesText={__en={"Speak with Mayara Brightwing in the Burning Steppes.",},__ru={"Поговорите с Майрой в Пылающих степях.",},},parentQuest=0,questFlags=72,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=4294967373,specialFlags=0,startedBy={{2285,},},zoneOrSort=1583,},[4768]={finishedBy={{9078,},},name={__en="The Darkstone Tablet",__ru="Табличка Темнокамня",},n