ders.","",},__ru={"Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука.","","Судя по всему, яйца надо искать недалеко от пауков.",},},parentQuest=0,questFlags=8,questLevel=59,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{10260,},},zoneOrSort=1583,},[4866]={finishedBy={{9563,},},name={__en="Mother's Milk",__ru="Материнское молоко",},nextQuestInChain=0,objectives={{{9563,[3]=5,},},},objectivesText={__en={"In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.",},__ru={"Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд.",},},parentQuest=0,questFlags=10,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=2,startedBy={{9563,},},zoneOrSort=1583,},[4867]={finishedBy={{10799,},},name={__en="Urok Doomhowl",__ru="Аррок Смертный Вопль",},nextQuestInChain=0,objectives={[3]={{12712,[3]=0,},},},objectivesText={__en={"Read Warosh's Scroll. Bring Warosh's Mojo to Warosh.",},__ru={"Прочитайте записку Вароша. Принесите Варошу его амулет.",},},parentQuest=0,questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{10799,},},zoneOrSort=1583,},[4903]={finishedBy={{9077,},},name={__en="Warlord's Command",__ru="Приказ полководца",},nextQuestInChain=4941,objectives={{{9568,[3]=0,},{9196,[3]=0,},{9237,[3]=0,},},[3]={{12562,[3]=0,},},},objectivesText={__en={"Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.",},__ru={"Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них в