,requiredSkill={164,270,},specialFlags=2,startedBy={{10918,},},zoneOrSort=-121,},[5127]={finishedBy={{10918,},},name={__en="The Demon Forge",__ru="Демонова кузня",},nextQuestInChain=0,objectives={[3]={{12847,[3]=0,},{12806,[3]=0,},},},objectivesText={__en={"Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.","","You must also find the Unforged Rune Covered Breastplate.","","Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.",},__ru={"Отправляйтесь на пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей.","","Кроме того, вам нужно найти заготовку рунической кирасы.","","Отнесите пику и кирасу Лораксу в Зимних Ключах.",},},parentQuest=0,preQuestSingle={5126,},questFlags=64,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,requiredSkill={164,270,},specialFlags=0,startedBy={{10918,},},zoneOrSort=1583,},[5160]={finishedBy={{10929,},},name={__en="The Matron Protectorate",__ru="Матрона-защитница",},nextQuestInChain=5161,objectives={},objectivesText={__en={"Travel to Winterspring and find Haleh. Give her Awbee's scale.",},__ru={"Дойдите до Зимних Ключей и найдите Халех. Отдайте ей пластину чешуи Ауби.",},},parentQuest=0,questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{10740,},},zoneOrSort=1583,},[5161]={finishedBy={{10929,},},name={__en="Wrath of the Blue Flight",__ru="Ярость Синих драконов",},nextQuestInChain=5162,objectives={},objectivesText={__en={"Speak with Haleh if you wish to continue.",},__ru={"Если у вас есть желание продолжить, поговорите снова с Халех.",},},parentQuest=0,preQuestSingle={5160,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{10929,},},zoneOrSort=618,},[5162]={finishedBy={{10976,},},name={__en="Wrath of the Blue Flight",__ru="Гнев синих драконов",},nextQuestInChain=5164,objectives={},objectivesText={__en={"Speak with Jeziba in the Plaguelands. He resides in Andorhal.",},__ru={"Поговорите с Джезибой в Чумных землях. Он обитает в Андорале.",},},parentQuest=0,preQuestSingle={5161,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{10929,},},zoneOrSort=28,},[5164]={finishedBy={[2]={176192,},},name={__en="Catalogue of the Wayward",__ru="Перечень Заблудших",},nextQuestInChain=0,objectives={},objectivesText={__en={"Read from the Catalogue of the Wayward.","",},__ru={"Прочитайте перечень Заблудших.",},},parentQuest=0,preQuestSingle={5162,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{10976,},},zoneOrSort=28,},[5212]={finishedBy={{11035,},},name={__en="The Flesh Does Not Lie",__ru="Плоть не лжет",},nextQuestInChain=5213,objectives={[3]={{13174,[3]=0,},},},objectivesText={__en={"Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.",},__ru={"Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11035,},},zoneOrSort=2017,},[5213]={finishedBy={{11035,},},name={__en="The Active Agent",__ru="Вирус чумы",},nextQuestInChain=0,objectives={[3]={{13176,[3]=0,},},},objectivesText={__en={"Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.","",},__ru={"Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.",},},parentQuest=0,preQuestSingle={5212,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11035,},},zoneOrSort=2017,},[5214]={finishedBy={{11033,},},name={__en="The Great Ezra Grimm",__ru="Великий Эзра Гримм",},nextQuestInChain=0,objectives={[3]={{13172,[3]=0,},},},objectivesText={__en={"Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done.",},__ru={"Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11033,},},zoneOrSort=2017,},[5243]={finishedBy={{11036,},},name={__en="Houses of the Holy",__ru="Святая вода",},nextQuestInChain=0,objectives={[3]={{13180,[3]=0,},},},objectivesText={__en={"Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.",},__ru={"Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11036,},},zoneOrSort=2017,},[5251]={finishedBy={{11039,},},name={__en="The Archivist",__ru="Архивариус",},nextQuestInChain=5262,objectives={{{10811,[3]=0,},},{{176245,"Archive Burned",0,},},},objectivesText={__en={"Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.",},__ru={"Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11039,},},zoneOrSort=2017,},[5262]={finishedBy={{11039,},},name={__en="The Truth Comes Crashing Down",__ru="Ошеломляющая истина",},nextQuestInChain=5263,objectives={},objectivesText={__en={"Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.",},__ru={"Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли.",},},parentQuest=0,preQuestSingle={5251,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={[3]={13250,},},zoneOrSort=2017,},[5263]={finishedBy={{11039,},},name={__en="Above and Beyond",__ru="Быстрее, выше, сильнее",},nextQuestInChain=5264,objectives={[3]={{13251,[3]=0,},},},objectivesText={__en={"Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.","",},__ru={"Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу.",},},parentQuest=0,preQuestSingle={5262,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11039,},},zoneOrSort=2017,},[5264]={finishedBy={{11034,},},name={__en="Lord Maxwell Tyrosus",__ru="Лорд Максвелл Тиросс",},nextQuestInChain=5265,objectives={},objectivesText={__en={"Speak with Lord Maxwell Tyrosus. He is inside the church.",},__ru={"Поговорите с лордом Максвеллом Тироссом. Вы найдете его внутри храма.",},},parentQuest=0,preQuestSingle={5263,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11039,},},zoneOrSort=139,},[5265]={finishedBy={[2]={176317,},},name={__en="The Argent Hold",__ru="Серебряный Оплот",},nextQuestInChain=0,objectives={},objectivesText={__en={"Open the Argent Hold and claim your reward.",},__ru={"Откройте Серебряный Оплот и получите награду.",},},parentQuest=0,preQuestSingle={5264,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11034,},},zoneOrSort=139,},[5281]={finishedBy={{11140,},},name={__en="The Restless Souls",__ru="Мятущиеся души",},nextQuestInChain=5282,objectives={},objectivesText={__en={"Find Egan. You only know that he was last seen around Stratholme.",},__ru={"Найдите Эгана. В последний раз его видели недалеко от Стратхольма.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11038,},},zoneOrSort=139,},[5282]={finishedBy={{11140,},},name={__en="The Restless Souls",__ru="Мятущиеся души",},nextQuestInChain=0,objectives={{{11122,"Souls Freed",0,},},},objectivesText={__en={"Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!","","Free 15 Restless Souls and return to Egan.",},__ru={"Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.","","Освободите 15 неупокоенных душ и возвращайтесь к Эгану.",},},parentQuest=0,preQuestSingle={5281,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11140,},},zoneOrSort=2017,},[5341]={finishedBy={{11022,},},name={__en="Barov Family Fortune",__ru="Сокровище Баровых",},nextQuestInChain=5342,objectives={[3]={{13471,[3]=0,},{13448,[3]=0,},{13450,[3]=0,},{13451,[3]=0,},},},objectivesText={__en={"Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.",},__ru={"Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=52,requiredRaces=8589934770,specialFlags=0,startedBy={{11022,},},zoneOrSort=2057,},[5342]={finishedBy={{11022,},},name={__en="The Last Barov",__ru="Последний из Баровых",},nextQuestInChain=0,objectives={[3]={{13469,[3]=0,},},},objectivesText={__en={"Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.","","Be warned, Weldon will probably be well protected by Alliance scum.",},__ru={"Отправляйтесь в Лагерь Промозглого Ветра – на земли Альянса – и убейте Велдона Барова. Отнесите его голову Алексию Барову.","","Соблюдайте осторожность – скорее всего, Велдона охраняет мразь Альянса.",},},parentQuest=0,preQuestSingle={5341,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=52,requiredRaces=8589934770,specialFlags=0,startedBy={{11022,},},zoneOrSort=28,},[5343]={finishedBy={{11023,},},name={__en="Barov Family Fortune",__ru="Сокровище Баровых",},nextQuestInChain=5344,objectives={[3]={{13471,[3]=0,},{13448,[3]=0,},{13450,[3]=0,},{13451,[3]=0,},},},objectivesText={__en={"Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.",},__ru={"Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=52,requiredRaces=4294967373,specialFlags=0,startedBy={{11023,},},zoneOrSort=2057,},[5344]={finishedBy={{11023,},},name={__en="The Last Barov",__ru="Последний из Баровых",},nextQuestInChain=0,objectives={[3]={{13470,[3]=0,},},},objectivesText={__en={"Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.","","Be warned, Alexi will probably be well protected by Horde filth.",},__ru={"Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Велдону Барову.","","Соблюдайте осторожность – скорее всего, Алексия охраняет ордынская мразь.",},},parentQuest=0,preQuestSingle={5343,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=52,requiredRaces=4294967373,specialFlags=0,startedBy={{11023,},},zoneOrSort=28,},[5382]={finishedBy={{11216,},},name={__en="Doctor Theolen Krastinov, the Butcher",__ru="Доктор Теолен Крастинов – Мясник",},nextQuestInChain=5515,objectives={{{11261,[3]=0,},},{{176544,"Remains of Eva Sarkhoff Burned",0,},{176545,"Remains of Lucien Sarkhoff Burned",0,},},},objectivesText={__en={"Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.","",},__ru={"Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11216,},},zoneOrSort=2057,},[5384]={finishedBy={{11216,},},name={__en="Kirtonos the Herald",__ru="Киртонос Глашатай",},nextQuestInChain=5461,objectives={{{10506,[3]=0,},},},objectivesText={__en={"Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.","","Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.","",},__ru={"Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.","","Сражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф.",},},parentQuest=0,preQuestSingle={5515,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={{11216,},},zoneOrSort=2057,},[5461]={finishedBy={{11286,},},name={__en="The Human, Ras Frostwhisper",__ru="Рас Ледяной Шепот – человек",},nextQuestInChain=5462,objectives={[3]={{13585,[3]=0,},},},objectivesText={__en={"Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.",},__ru={"Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку.",},},parentQuest=0,preQuestSingle={5384,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{11286,},},zoneOrSort=28,},[5462]={finishedBy={{11036,},},name={__en="The Dying, Ras Frostwhisper",__ru="Рас Ледяной Шепот – гибель",},nextQuestInChain=5463,objectives={},objectivesText={__en={"Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.",},__ru={"Отправляйтесь в часовню Светлых надежд в Восточных Чумных землях и найдите Леонида Бартоломея Чтимого. Покажите ему книгу Воспоминаний и расскажите обо всем, о чем удалось узнать.",},},parentQuest=0,preQuestSingle={5461,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{11286,},},zoneOrSort=28,},[5463]={finishedBy={[2]={176631,},},name={__en="Menethil's Gift",__ru="Дар Менетила",},nextQuestInChain=5464,objectives={},objectivesText={__en={"Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.",},__ru={"Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю.",},},parentQuest=0,preQuestSingle={5462,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{11036,},},zoneOrSort=2017,},[5464]={finishedBy={{11036,},},name={__en="Menethil's Gift",__ru="Дар Менетила",},nextQuestInChain=5465,objectives={},objectivesText={__en={"Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.",},__ru={"Отнесите Книгу Души Леониду Бартоломею в Восточные Чумные земли.",},},parentQuest=0,preQuestSingle={5463,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={[2]={176631,},},zoneOrSort=139,},[5465]={finishedBy={{11286,},},name={__en="Soulbound Keepsake",__ru="Книга Души",},nextQuestInChain=5466,objectives={},objectivesText={__en={"Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.",},__ru={"Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души.",},},parentQuest=0,preQuestSingle={5464,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{11036,},},zoneOrSort=28,},[5466]={finishedBy={{11286,},},name={__en="The Lich, Ras Frostwhisper",__ru="Рас Снегошепот – лич",},nextQuestInChain=0,objectives={[3]={{13626,[3]=0,},},},objectivesText={__en={"Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.",},__ru={"Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку.",},},parentQuest=0,preQuestSingle={5465,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=0,startedBy={{11286,},},zoneOrSort=2057,},[5515]={finishedBy={{11216,},},name={__en="Krastinov's Bag of Horrors",__ru="Мешок ужасов Крастинова",},nextQuestInChain=5384,objectives={[3]={{13725,[3]=0,},},},objectivesText={__en={"Locate Jandice Barov in