,},},name={__en="Hidden Enemies",__ru="Тайные враги",},nextQuestInChain=0,objectives={},objectivesText={__en={"Speak to Thrall in Orgrimmar and tell him what you've learned.",},__ru={"Поговорите с Траллом в Оргриммаре.",},},parentQuest=0,preQuestSingle={5729,},questFlags=8,questLevel=16,requiredClasses=0,requiredLevel=9,requiredRaces=8589934770,specialFlags=0,startedBy={{3216,},},zoneOrSort=1637,},[5742]={finishedBy={{1855,},},name={__en="Redemption",__ru="Спасение",},nextQuestInChain=5781,objectives={{{1855,[3]=5,},},},objectivesText={__en={"Listen to what Tirion Fordring has to say.",},__ru={"Выслушайте Тириона Фордринга.",},},parentQuest=0,preQuestGroup={5542,5543,5544,},questFlags=10,questLevel=56,requiredClasses=0,requiredLevel=52,requiredRaces=0,specialFlags=2,startedBy={{1855,},},zoneOrSort=139,},[5761]={finishedBy={{3216,},},name={__en="Slaying the Beast",__ru="Убить тварь",},nextQuestInChain=0,objectives={[3]={{14540,[3]=0,},},},objectivesText={__en={"Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.",},__ru={"Спуститесь в Огненную пропасть, убейте Тарагамана Ненасытного и принесите его сердце Нииру Огненному Клинку в Оргриммаре.",},},parentQuest=0,questFlags=8,questLevel=16,requiredClasses=0,requiredLevel=9,requiredRaces=8589934770,specialFlags=0,startedBy={{3216,},},zoneOrSort=2437,},[5781]={finishedBy={{1855,},},name={__en="Of Forgotten Memories",__ru="Символ ушедших дней",},nextQuestInChain=5845,objectives={[3]={{14613,[3]=0,},},},objectivesText={__en={"Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.",},__ru={"Отправляйтесь в Крипту – в самой южной части Восточных Чумных земель – и добудьте молот Таэлана. Отнесите его Тириону Фордрингу.",},},parentQuest=0,preQuestSingle={5742,},questFlags=8,questLevel=57,requiredClasses=0,requiredLevel=52,requiredRaces=0,specialFlags=