йство",},nextQuestInChain=0,objectives={[3]={{15448,[3]=0,},},},objectivesText={__en={"Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.",},__ru={"Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее, чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль.",},},parentQuest=0,questFlags=0,questLevel=58,requiredClasses=0,requiredLevel=54,requiredRaces=8589934770,specialFlags=0,startedBy={{11878,},},zoneOrSort=139,},[6042]={finishedBy={{11878,},},name={__en="Un-Life's Little Annoyances",__ru="Мелочи нежизни",},nextQuestInChain=0,objectives={{{8601,[3]=0,},{8602,[3]=0,},},},objectivesText={__en={"Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.",},__ru={"Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостеню.",},},parentQuest=0,questFlags=8,questLevel=58,requiredClasses=0,requiredLevel=54,requiredRaces=8589934770,specialFlags=0,startedBy={{11878,},},zoneOrSort=139,},[6133]={finishedBy={{11878,},},name={__en="The Ranger Lord's Behest",__ru="Охота на cледопытов",},nextQuestInChain=0,objectives={{{8565,[3]=0,},{8564,[3]=0,},{8563,[3]=0,},},[3]={{15847,[3]=0,},},},objectivesText={__en={"Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.","","You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.",},__ru={"Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель'Таласа. Документ находится где-то в Сторожке Кель'Литиен.","","Также убейте 8 следопытов, 8 разведчиц дорог и 8 лесников.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=54,requiredRaces=8589934770,specialFlags=0,startedBy={{11878,},},zoneOrSort=139,},[6135]={finishedBy={{11878,},},name={__en="Duskwing, Oh How I Hate Thee...",__ru="Проклятый Тенекрыл",},nextQuestInChain=0,objectives={[3]={{15850,[3]=0,},},},objectivesText={__en={"Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.","","It is said that Duskwing roams the countryside to the north of Marris Stead.",},__ru={"Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостеню.","","Говорят, Тенекрыл рыщет в землях к северу от имения Марриса.",},},parentQuest=0,preQuestGroup={6022,6042,6133,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=56,requiredRaces=8589934770,specialFlags=0,startedBy={{11878,},},zoneOrSort=139,},[6136]={finishedBy={{11878,},},name={__en="The Corpulent One",__ru="Огромный червь",},nextQuestInChain=0,objectives={{{11896,[3]=0,},},},objectivesText={__en={"Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete.",},__ru={"Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостеню по выполнению задания.",},},parentQuest=0,preQuestGroup={6022,6042,6133,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=56,requiredRaces=8589934770,specialFlags=0,startedBy={{11878,},},zoneOrSort=139,},[6163]={finishedBy={{11878,},},name={__en="Ramstein",__ru="Рамштейн",},nextQuestInChain=0,objectives={[3]={{15880,[3]=0,},},},objectivesText={__en={"Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.",},__ru={"Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира.",},},parentQuest=0,preQuestGroup={6135,6136,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=56,requiredRaces=8589934770,specialFlags=0,startedBy={{11878,},},zoneOrSort=2017,},[6402]={finishedBy={{12580,},},name={__en="Stormwind Rendezvous",__ru="Встреча в Штормграде",},nextQuestInChain=6403,objectives={},objectivesText={__en={"Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived.",},__ru={"Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии.",},},parentQuest=0,preQuestSingle={4322,},questFlags=72,questLevel=60,requiredClasses=0,requiredLevel=50,requiredRaces=4294967373,specialFlags=0,startedBy={{9560,},},zoneOrSort=1519,},[6403]={finishedBy={{1748,},},name={__en="The Great Masquerade",__ru="Великий Маскарад",},nextQuestInChain=6501,objectives={},objectivesText={__en={"Follow Reginald Windsor through Stormwind. Protect him from harm!",},__ru={"Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!",},},parentQuest=0,preQuestSingle={6402,},questFlags=66,questLevel=60,requiredClasses=0,requiredLevel=50,requiredRaces=4294967373,specialFlags=2,startedBy={{12580,},},zoneOrSort=1519,},[6501]={finishedBy={{10929,},},name={__en="The Dragon's Eye",__ru="Око дракона",},nextQuestInChain=6502,objectives={},objectivesText={__en={"You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist.",},__ru={"Найдите существа, способные вернуть силу фрагменту амулета Ока дракона. Все, что об этих существах известно – это то, что они есть.",},},parentQuest=0,preQuestSingle={6403,},questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=50,requiredRaces=4294967373,specialFlags=0,startedBy={{1748,},},zoneOrSort=1519,},[6502]={finishedBy={{10929,},},name={__en="Drakefire Amulet",__ru="Амулет Пламени дракона",},nextQuestInChain=0,objectives={[3]={{16663,[3]=0,},},},objectivesText={__en={"You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.",},__ru={"Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы.",},},parentQuest=0,preQuestSingle={6501,},questFlags=72,questLevel=60,requiredClasses=0,requiredLevel=50,requiredRaces=4294967373,specialFlags=0,startedBy={{10929,},},zoneOrSort=1583,},[6521]={finishedBy={{2425,},},name={__en="An Unholy Alliance",__ru="Нечестивый союз",},nextQuestInChain=0,objectives={[3]={{17009,[3]=0,},},},objectivesText={__en={"Bring Ambassador Malcin's Head to Varimathras in the Undercity.",},__ru={"Принести голову посла Малкина Вариматрасу в Подгород.",},},parentQuest=0,preQuestSingle={6522,},questFlags=8,questLevel=36,requiredClasses=0,requiredLevel=28,requiredRaces=8589934770,specialFlags=0,startedBy={{2425,},},zoneOrSort=722,},[6522]={finishedBy={{2425,},},name={__en="An Unholy Alliance",__ru="Нечестивый союз",},nextQuestInChain=6521,objectives={},objectivesText={__en={"Take the Small Scroll to Varimathras in the Undercity.",},__ru={"Отнесите маленький свиток Вариматрасу в Подгород.",},},parentQuest=0,questFlags=0,questLevel=36,requiredClasses=0,requiredLevel=28,requiredRaces=8589934770,specialFlags=0,startedBy={[3]={17008,},},zoneOrSort=722,},[6561]={finishedBy={{9087,},},name={__en="Blackfathom Villainy",__ru="Жестокость Черных Глубин",},nextQuestInChain=0,objectives={[3]={{5881,[3]=0,},},},objectivesText={__en={"Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.",},__ru={"Принесите голову Повелителя сумрака Келриса Башане Руническому Тотему в Громовой Утес.",},},parentQuest=0,questFlags=8,questLevel=27,requiredClasses=0,requiredLevel=18,requiredRaces=8589934770,specialFlags=0,startedBy={{4787,},},zoneOrSort=719,},[6562]={finishedBy={{12736,},},name={__en="Trouble in the Deeps",__ru="Угроза из Глубин",},nextQuestInChain=6563,objectives={},objectivesText={__en={"Speak to Je'neu 