eradras and return to Keeper Marandis at Nijel's Point in Desolace.",},__ru={"Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.",},},parentQuest=0,questFlags=8,questLevel=51,requiredClasses=0,requiredLevel=45,requiredRaces=4294967373,specialFlags=0,startedBy={{13698,},},zoneOrSort=2100,},[7066]={finishedBy={{11832,},},name={__en="Seed of Life",__ru="Семя Жизни",},nextQuestInChain=0,objectives={},objectivesText={__en={"Seek out Remulos in Moonglade and give him the Seed of Life.",},__ru={"Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни.",},},parentQuest=0,questFlags=0,questLevel=51,requiredClasses=0,requiredLevel=45,requiredRaces=0,specialFlags=0,startedBy={{12238,},},zoneOrSort=2100,},[7067]={finishedBy={{13717,},},name={__en="The Pariah's Instructions",__ru="Инструкции кентавра-парии",},nextQuestInChain=0,objectives={[3]={{17758,[3]=0,},},},objectivesText={__en={"Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.",},__ru={"Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей.",},},parentQuest=0,questFlags=0,questLevel=48,requiredClasses=0,requiredLevel=39,requiredRaces=0,specialFlags=0,startedBy={{13717,},},zoneOrSort=2100,},[7068]={finishedBy={{7311,},},name={__en="Shadowshard Fragments",__ru="Фрагменты осколка сумрака",},nextQuestInChain=0,objectives={[3]={{17756,[3]=0,},},},objectivesText={__en={"Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.",},__ru={"Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар.",},},parentQuest=0,questFlags=8,questLevel=42,requiredClasses=0,requiredLevel=39,requiredRaces=8589934770,specialFlags=0,startedBy={{7311,},},zoneOrSort=2100,},[7070]={finishedBy={{4967,},},name={__en="Shadowshard Fragments",__ru="Фрагменты осколка сумрака",},nextQuestInChain=0,objectives={[3]={{17756,[3]=0,},},},objectivesText={__en={"Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.",},__ru={"Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей.",},},parentQuest=0,questFlags=8,questLevel=42,requiredClasses=0,requiredLevel=39,requiredRaces=4294967373,specialFlags=0,startedBy={{4967,},},zoneOrSort=2100,},[7201]={finishedBy={{9078,},},name={__en="The Last Element",__ru="Последняя Стихия",},nextQuestInChain=0,objectives={[3]={{11129,[3]=0,},},},objectivesText={__en={"Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.","",},__ru={"Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей.",},},parentQuest=0,preQuestSingle={3906,},questFlags=8,questLevel=54,requiredClasses=0,requiredLevel=48,requiredRaces=8589934770,specialFlags=0,startedBy={{9078,},},zoneOrSort=1584,},[7429]={finishedBy={{14338,},},name={__en="Free Knot!",__ru="Освободите Нотта!",},nextQuestInChain=0,objectives={[3]={{18250,[3]=0,},},},parentQuest=0,preQuestSingle={5525,},questFlags=264,questLevel=60,requiredClasses=0,requiredLevel=57,requiredRaces=0,specialFlags=1,startedBy={{14338,},},zoneOrSort=2557,},[7441]={finishedBy={{14355,},},name={__en="Pusillin and the Elder Azj'Tordin",__ru="Пузиллин и старейший Аж'Тордин",},nextQuestInChain=0,objectives={[3]={{18261,[3]=0,},},},objectivesText={__en={"Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.","","Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.",},__ru={"Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина.","","Если добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе.",},},parentQuest=0,questFlags=8,questLevel=58,requiredClasses=0,requiredLevel=54,requiredRaces=0,specialFlags=0,startedBy={{14355,},},zoneOrSort=2557,},[7461]={finishedBy={{14358,},},name={__en="The Madness Within",__ru="Древнее безумие",},nextQuestInChain=7877,objectives={{{11496,[3]=0,},{11486,[3]=0,},},},objectivesText={__en={"You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.","","Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.","","Return to the Shen'dralar Ancient in the courtyard should you complete this quest.",},__ru={"Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется.","","Войдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.","","Если задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар.",},},parentQuest=0,questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=56,requiredRaces=0,specialFlags=0,startedBy={{14358,},},zoneOrSort=2557,},[7462]={finishedBy={[2]={179517,},},name={__en="The Treasure of the Shen'dralar",__ru="Сокровище Шен'дралар",},nextQuestInChain=0,objectives={},objectivesText={__en={"Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",},__ru={"Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!",},},parentQuest=0,preQuestSingle={7461,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=56,requiredRaces=4294967373,