3,requiredLevel=60,requiredRaces=0,specialFlags=0,startedBy={[3]={18513,},},zoneOrSort=2557,},[7509]={finishedBy={{14368,},},name={__en="The Forging of Quel'Serrar",__ru="Ковка Кель-Серрара",},nextQuestInChain=0,objectives={[3]={{18492,[3]=0,},},},objectivesText={__en={"You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.","","The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.","","Do this and Quel'Serrar will be yours.",},__ru={"Заставьте Ониксию дохнуть своим огненным дыханием на потускневший древний клинок. После этого схватите раскаленный древний клинок. Имейте в виду, что раскаленным он останется ненадолго, так что медлить не следует!","","Последнее, что нужно сделать – это убить драконицу и вонзить раскаленный древний клинок в ее труп.","","Сделайте это – и Кель-Серрар навеки станет вашим!",},},parentQuest=0,preQuestSingle={7508,},questFlags=64,questLevel=60,requiredClasses=3,requiredLevel=60,requiredRaces=0,specialFlags=0,startedBy={{14368,},},zoneOrSort=2159,},[7604]={finishedBy={{12944,},},name={__en="A Binding Contract",__ru="Заключение договора",},nextQuestInChain=0,objectives={[3]={{17203,[3]=0,},},},objectivesText={__en={"Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.",},__ru={"Подпишите договор с представителем братства Тория Локтосом Недобрым Торговцем, если вам нужен чертеж сульфуронского молота.",},},parentQuest=0,questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=60,requiredRaces=0,specialFlags=0,startedBy={[3]={18628,},},zoneOrSort=1584,},[7703]={finishedBy={{14325,},},name={__en="Unfinished Gordok Business",__ru="Неоконченное дело Гордоков",},nextQuestInChain=0,objectives={[3]={{18336,[3]=0,},},},objectivesText={__en={"Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.","","According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",},__ru={"Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.","","По словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.",},},parentQuest=0,questFlags=0,questLevel=60,requiredClasses=0,requiredLevel=56,requiredRaces=0,specialFlags=0,startedBy={{14325,},},zoneOrSort=2557,},[7761]={finishedBy={[2]={179880,},},name={__en="Blackhand's Command",__ru="Приказ Чернорука",},nextQuestInChain=0,objectives={},objectivesText={__en={"That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.","","The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.",},__ru={"Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.","","В письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить.",},},parentQuest=0,questFlags=64,questLevel=60,requiredClasses=0,requiredLevel=55,requiredRaces=0,specialFlags=0,startedBy={[3]={18987,},},zoneOrSort=1583,},[7877]={finishedBy={[2]={179517,},},name={__en="The Treasure of the Shen'dralar",__ru="Сокровище Шен'дралар",},nextQuestInChain=0,objectives={},objectivesText={__en={"Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",},__ru={"Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!",},},parentQuest=0,preQuestSingle={7461,},questFlags=8,questLevel=60,requiredClasses=0,requiredLevel=56,requiredRaces=0,specialFlags=0,startedBy={{14358,},},zoneOrSort=2557,},[8181]={finishedBy={{8579,},},name={__en="Confront